nquantity']*$product['fprice'])).' '.$lbl_vnd;									?>							  </td>						   </tr>						   <?php endforeach; ?>						   <tr>							  <td colspan="4" style="text-align:right"><b><?php echo "Phí giao hàng" ?> : </b></td>							  <td style="text-align:right;color:red;"><b><?php if($obj_order_view['ccost']!=0) echo Fview_text(number_format($obj_order_view['ccost'])).' '.$lbl_vnd; else echo "0 VNĐ"; ?></b></td>						   </tr>						   <?php if($obj_order_view['cgiam_gia']!="" && $obj_order_view['cgiam_gia']!=0) { ?>						   <tr>							  <td colspan="4" style="text-align:right"><b><?php echo "Giảm giá (cho đơn hàng đầu tiên)" ?> : </b></td>							  <td style="text-align:right;color:red;"><b><?php echo '- '.Fview_text(number_format($obj_order_view['cgiam_gia'])).' '.$lbl_vnd ?></b></td>						   </tr>						   <?php } ?>						   <tr>							  <td colspan="4" style="text-align:right"><b><?php echo "Tổng tiền" ?> : </b></td>							  <td style="text-align:right;color:red;"><b><?php echo Fview_text(number_format($obj_order_view['ntotal'])).' '.$lbl_vnd ?></b></td>						   </tr>						</tbody>					 </table>					 <table class="table table-striped">						<tbody>						   <tr>							  <td class="key" width="100" align="right">Trạng thái đơn hàng</td>							  <td width="400"><?php echo $gencbo_order_status_list ;?></td>						   </tr>							<tr>							  <td class="key" width="100" align="right">Admin Ghi chú</td>							  <td width="400">													  <div class="form-input">                     <textarea class="form-control" name="cadmin_note" placeholder=" " style="height:100px;" /><?php echo $cadmin_note; ?></textarea>                  </div>							  </td>						   </tr>						<tbody>									 </table>				  				  <input name="hidden_nid" type="hidden" value = "<?php echo $nid; ?>"  />				  <input name="hidden_event" type="hidden" value = "<?php echo $event; ?>"  />				  <input type="hidden" name="hidden_button"  value = "" />				              